    let current = Syntax(self)
    if current.parent?.is(async.self) ?? false,
      current.parent?.parent?.is(CodeBlockItemListSyntax.self) ?? false,
      current.parent?.parent?.parent?.is(SourceFileSyntax.self) ?? false
    {
      return true
    }
    return false
  }
}
